def standard_captures(Pickable, using, pack_id):
    return Pickable.objects.using(using).filter(
        models.Q(qualifier="", slot_type__name="Lasting Injury")
        | models.Q(qualifier="vehicle", slot_type__name="Lasting Damage"),
        pack_id=pack_id,
        name="Captured",
        slot_type__pack_id=pack_id,
    )


def standard_escape_results(Pickable, using, slot):
    return Pickable.objects.using(using).filter(
        pack_id=slot.pack_id,
        slot_type_id=slot.slot_type_id,
        name__in=["Executed", "Ransomed", "Daring Escape"],
        qualifier="",
    )


def validate_status_modifier(Modifier, using, slot, modifier):
    expected = (
        Modifier.objects.using(using)
        .filter(
            pk=modifier.pk,
            targets_miniature__reach="every_model",
            adds_assignable__slot_id=slot.pk,
        )
        .annotate(status_conditions=models.Count("targets_miniature__has_status"))
        .filter(
            status_conditions=1,
            targets_miniature__has_status__status="captured",
            targets_miniature__has_subtypes__isnull=True,
            targets_miniature__is_profile__isnull=True,
            targets_miniature__is_profile_type__isnull=True,
            targets_miniature__has_pickable__isnull=True,
            targets_miniature__counter_at_least__isnull=True,
        )
    )
    if not expected.exists():
        raise RuntimeError(
            'The modifier "Captured models: Escape" has a different scope or effect. '
            "Rename it before changing standard Escape content."
        )


def update_standard_choices(apps, schema_editor):
    """Change standard content only; existing player history stays untouched."""
    from django.conf import settings

    using = schema_editor.connection.alias
    Slot = apps.get_model("library", "Slot")
    Pickable = apps.get_model("library", "Pickable")
    Modifier = apps.get_model("library", "Modifier")
    GangType = apps.get_model("library", "GangType")
    slot = (
        Slot.objects.using(using)
        .filter(
            name="Escape", qualifier="", pack__slug=settings.DEFAULT_CONTENT_PACK_SLUG
        )
        .first()
    )
    if slot is None:
        return
    modifier = (
        Modifier.objects.using(using)
        .filter(pack_id=slot.pack_id, name__iexact="Captured models: Escape")
        .first()
    )
    if modifier is not None:
        validate_status_modifier(Modifier, using, slot, modifier)
    Slot.objects.using(using).filter(pk=slot.pk).update(follows_status=True)
    captures = standard_captures(Pickable, using, slot.pack_id)
    captures.update(record_only=True)
    for result in captures:
        result.modifiers.remove(
            *result.modifiers.using(using).filter(
                pack_id=slot.pack_id,
                name__iexact="Captured: rolls on the Escape table",
                adds_assignable__slot_id=slot.pk,
            )
        )
    standard_escape_results(Pickable, using, slot).update(record_only=True)
    if modifier is None:
        scope = (
            apps.get_model("library", "TargetsMiniature")
            .objects.using(using)
            .create(reach="every_model")
        )
        apps.get_model("library", "HasStatus").objects.using(using).create(
            scope_id=scope.pk, status="captured"
        )
        effect = (
            apps.get_model("library", "AddsAssignable")
            .objects.using(using)
            .create(slot_id=slot.pk)
        )
        modifier = Modifier.objects.using(using).create(
            name="Captured models: Escape",
            pack_id=slot.pack_id,
            targets_miniature_id=scope.pk,
            adds_assignable_id=effect.pk,
        )
    for gang_type in GangType.objects.using(using).filter(
        pack_id=slot.pack_id, name__in=STANDARD_GANG_TYPES, qualifier=""
    ):
        gang_type.modifiers.add(modifier)


def restore_standard_choices(apps, schema_editor):
    """Restore the old grant before dropping the status condition table."""
    from django.conf import settings

    using = schema_editor.connection.alias
    Slot = apps.get_model("library", "Slot")
    Pickable = apps.get_model("library", "Pickable")
    Modifier = apps.get_model("library", "Modifier")
    slot = (
        Slot.objects.using(using)
        .filter(
            name="Escape", qualifier="", pack__slug=settings.DEFAULT_CONTENT_PACK_SLUG
        )
        .first()
    )
    if slot is None:
        return
    modifiers = Modifier.objects.using(using).filter(
        pack_id=slot.pack_id, name__iexact="Captured models: Escape"
    )
    for modifier in modifiers:
        validate_status_modifier(Modifier, using, slot, modifier)
    parts = list(modifiers.values_list("targets_miniature_id", "adds_assignable_id"))
    modifiers.delete()
    apps.get_model("library", "TargetsMiniature").objects.using(using).filter(
        pk__in=[scope_id for scope_id, _ in parts]
    ).delete()
    apps.get_model("library", "AddsAssignable").objects.using(using).filter(
        pk__in=[effect_id for _, effect_id in parts]
    ).delete()
    captures = standard_captures(Pickable, using, slot.pack_id)
    for result in captures:
        label = (
            f"{result.name} ({result.annotation})" if result.annotation else result.name
        )
        name = f"{label}: rolls on the {slot.label or slot.name} table"
        grant = (
            Modifier.objects.using(using)
            .filter(pack_id=slot.pack_id, name=name)
            .first()
        )
        if grant is None:
            scope = (
                apps.get_model("library", "TargetsMiniature")
                .objects.using(using)
                .create(reach="bearer")
            )
            effect = (
                apps.get_model("library", "AddsAssignable")
                .objects.using(using)
                .create(slot_id=slot.pk)
            )
            grant = Modifier.objects.using(using).create(
                name=name,
                pack_id=slot.pack_id,
                targets_miniature_id=scope.pk,
                adds_assignable_id=effect.pk,
            )
        result.modifiers.add(grant)
    captures.update(record_only=False)
    standard_escape_results(Pickable, using, slot).update(record_only=False)
    Slot.objects.using(using).filter(pk=slot.pk).update(follows_status=False)


